{
  "contract": "WAsgard",
  "closure": {
    "site_function": "wrap",
    "site_call": ".transferFrom",
    "functions": [
      "wrap"
    ],
    "justification": "wrap is the only function that writes to exposed storage variables deposits and lastWrapped."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "wrap"
    ],
    "nesting_bound": {
      "wrap": 1
    }
  },
  "phases": {
    "function": "wrap",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .transferFrom"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .transferFrom",
      "to_marker": "after .transferFrom"
    },
    "post": {
      "name": "post",
      "from_marker": "after .transferFrom",
      "to_marker": "exit"
    },
    "linearization_point": "after .transferFrom"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of deposits in flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances == _totalSupply + inFlight",
    "stable_formula": "_sum__balances == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances == _totalSupply",
    "rule": "The exposure invariant ensures that the sum of balances is conserved across the callback window, accounting for in-flight changes."
  }
}
